@pytest.mark.parametrize("option", ["-C", "--collect-only", "--collectonly"])
def test_collect_only_aliases(testdir, option):
    testdir.makepyfile(
        """
        def setup_module():
            raise AssertionError("collection must not run setup")

        def test_collected():
            raise AssertionError("collection must not run tests")
        """
    )
    result = testdir.runpytest(option)
    assert result.ret == ExitCode.OK
    result.stdout.fnmatch_lines(
        ["collected 1 item", "*<Function test_collected>*", "*no tests ran in*"]
    )


